package ama.transcript;

import ama.access.MeetingAccess;import ama.contract.IdentityContracts.Actor;import ama.contract.MinutesContracts.*;import ama.contract.ConfigArchiveContracts.ArchiveReadBudget;import ama.db.TransactionRunner;import javax.sql.DataSource;import java.util.*;import java.nio.charset.StandardCharsets;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.core.env.PropertyResolver;
import static ama.contract.MinutesContracts.*;import static ama.contract.MinutesContracts.FailureCode.*;

/** Independently constructed DB-only reads and immutable command acknowledgments. No provider/archive factory. */
public final class JdbcPublicationQueries {
 private final JdbcTemplate j;private final TransactionRunner tx;private final MeetingAccess access;private final PropertyResolver settings;private final Bounds commandBounds;
 private record Bounds(TranscriptAcquisitionBudget limits,ArchiveReadBudget archive,CanonicalBudget canonical){TranscriptAcquisitionBudget.Ledger ledger(){return limits.ledger(archive,canonical,()->false);}}
 private record Snapshot(Map<String,Object> root,Map<String,Object> publication,Map<String,List<Map<String,Object>>> rows,boolean owner){}
 private record Accepted(Map<String,Object> submission,Map<String,Object> task,Map<String,Object> confirmation,List<Map<String,Object>> executions,List<Map<String,Object>> attempts,String manifest){}
 public JdbcPublicationQueries(DataSource source,TransactionRunner tx,MeetingAccess access,PropertyResolver settings){this.tx=Objects.requireNonNull(tx);this.access=Objects.requireNonNull(access);this.settings=Objects.requireNonNull(settings);commandBounds=null;j=new JdbcTemplate(source);j.setQueryTimeout(2);}
 /** Same authority/DataSource and immutable configured budgets; no archive/provider lookup. */
 JdbcPublicationQueries(JdbcTranscriptAuthority authority,TranscriptAcquisitionBudget limits){tx=authority.transactionRunner();access=authority.savedAccess();settings=null;commandBounds=new Bounds(limits,authority.readBudget(),authority.canonicalBudget());j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);}
 private Bounds bounds(){if(commandBounds!=null)return commandBounds;try{return new Bounds(ConfiguredMinutes.acquisition(settings),ConfiguredMinutes.archiveBudget(settings),new CanonicalBudget(settings.getRequiredProperty("processing.bounds.canonical-bytes",Long.class),settings.getRequiredProperty("processing.bounds.canonical-depth",Integer.class),settings.getRequiredProperty("processing.bounds.canonical-nodes",Long.class),settings.getRequiredProperty("processing.bounds.canonical-string-utf8",Long.class),settings.getRequiredProperty("processing.bounds.canonical-scalars",Long.class)));}catch(IllegalArgumentException error){throw new ama.contract.TranscriptContracts.Failure(503,"PUBLICATION_READ_UNAVAILABLE");}}
 public Map<String,Object> current(Actor actor,String meeting){uuid(meeting);return tx.required(()->{access.require(access.lock(actor,meeting),MeetingAccess.Action.READ);var roots=header(meeting);if(roots.isEmpty())return JdbcMinutesSavedQueries.map("publication",null);var snapshot=capture(actor,meeting,roots.getFirst(),bounds());return JdbcMinutesSavedQueries.map("publication",PublicationReadProjection.status(snapshot.root(),snapshot.publication(),snapshot.rows(),snapshot.owner()));});}
 public Map<String,Object> detail(Actor actor,String meeting,String publication){uuid(meeting);uuid(publication);return tx.required(()->{access.require(access.lock(actor,meeting),MeetingAccess.Action.READ);var roots=header(meeting);if(roots.size()!=1||!publication.equals(roots.getFirst().get("id")))throw missing();var s=capture(actor,meeting,roots.getFirst(),bounds());return JdbcMinutesSavedQueries.map("publication",PublicationReadProjection.status(s.root(),s.publication(),s.rows(),s.owner()));});}
 public Map<String,Object> history(Actor actor,String meeting,String publication,boolean submissions,int limit,String cursor){
  uuid(meeting);uuid(publication);if(limit<1||limit>50)throw new IllegalArgumentException("Page limit out of range");String route=submissions?"submissions":"attempts";var before=PublicationHistoryCursor.decode(route,meeting,publication,cursor);
  return tx.required(()->{access.require(access.lock(actor,meeting),MeetingAccess.Action.EDIT);var roots=header(meeting);if(roots.size()!=1||!publication.equals(roots.getFirst().get("id")))throw missing();var bounds=bounds();var budget=bounds.ledger();var s=capture(actor,meeting,roots.getFirst(),bounds,budget);var args=new ArrayList<Object>();args.add(publication);String sql;
   if(submissions){sql="SELECT task_id,submission_no FROM publication_submission WHERE publication_id=?";if(before!=null){sql+=" AND submission_no<?";args.add(before.ordinal());}sql+=" ORDER BY submission_no DESC";}else{var query=attemptPage(publication,before);sql=query.sql();args=new ArrayList<>(query.args());}
   var page=page(sql,limit+1,budget,args.toArray());boolean more=page.size()>limit;if(more)page=page.subList(0,limit);var items=new ArrayList<Map<String,Object>>();for(var key:page){var matches=s.rows().get(submissions?"publication_submission":"publication_attempt").stream().filter(row->Objects.equals(row.get(submissions?"task_id":"id"),key.get(submissions?"task_id":"id"))).toList();require(matches.size()==1,PROVENANCE_UNAVAILABLE);var row=matches.getFirst();require(submissions?number(row,"submission_no")==number(key,"submission_no"):PublicationHistoryCursor.time(row.get("created_at")).equals(PublicationHistoryCursor.time(key.get("created_at"))),PROVENANCE_UNAVAILABLE);items.add(submissions?submissionView(row,s.rows()):attemptView(row,s.rows()));}
   return JdbcMinutesSavedQueries.map("items",List.copyOf(items),"hasMore",more,"nextCursor",more?PublicationHistoryCursor.encode(route,meeting,publication,page.getLast()):null,"observation",PublicationReadProjection.status(s.root(),s.publication(),s.rows(),true));
  });
 }
 public Map<String,Object> finalHistory(Actor actor,String meeting,int limit,String cursor){
  uuid(meeting);if(limit<1||limit>50)throw new IllegalArgumentException("Page limit out of range");var before=PublicationHistoryCursor.decode("finals",meeting,null,cursor);var budget=bounds().ledger();
  return tx.required(()->{access.require(access.lock(actor,meeting),MeetingAccess.Action.EDIT);var args=new ArrayList<Object>();args.add(meeting);if(before!=null)args.add(before.ordinal());var rows=page("SELECT id,meeting_revision,confirmed_by,confirmed_at,minutes_revision_id,element_set_id,transcript_confirmation_id FROM final_confirmation WHERE meeting_id=?"+(before==null?"":" AND meeting_revision<?")+" ORDER BY meeting_revision DESC",limit+1,budget,args.toArray());boolean more=rows.size()>limit;if(more)rows=rows.subList(0,limit);return JdbcMinutesSavedQueries.map("items",rows.stream().map(JdbcPublicationQueries::publicFinalHeader).toList(),"hasMore",more,"nextCursor",more?PublicationHistoryCursor.encode("finals",meeting,null,rows.getLast()):null);});
 }

 /** Existing command digests are supplied only after the controller's lossless normalization. */
 public Optional<Map<String,Object>> lookup(Actor actor,String meeting,String operation,String key,String... semantics){
  var identity=PublicationReplayIdentity.parse(operation,semantics);String requestHash=JdbcProcessingIntake.digest(semantics);
  JdbcMinutesFactsReader.independent();uuid(meeting);JdbcProcessingIntake.key(key);if(!Set.of("PUBLICATION_SUBMIT","PUBLICATION_RESUBMIT","PUBLICATION_LOCAL_RECOVERY","PUBLICATION_ZERO_EFFECT_RETRY").contains(operation))throw new IllegalArgumentException("Unknown publication command");
  String scope=JdbcProcessingIntake.digest(actor.enterpriseId(),meeting,operation,key);var bounds=bounds();var budget=bounds.ledger();
  var original=tx.required(()->{var receipt=command(scope);access.require(access.lock(actor,meeting),MeetingAccess.Action.EDIT);if(receipt==null)return null;matchCommand(receipt,actor,meeting,operation,key,requestHash);return accepted(meeting,(String)receipt.get("result_id"),operation,bounds,budget,identity);});
  if(original==null)return Optional.empty();
  // Original wire verification and hashing remain outside every DB/root transaction.
  var manifest=PublicationManifest.read(original.manifest(),budget);var submission=original.submission();for(String field:List.of("publicationId","confirmationId","providerId","libraryId","folderId","requesterId","businessKey","logicalRequestHash","executionRequestHash")){String column=switch(field){case "publicationId"->"publication_id";case "confirmationId"->"confirmation_id";case "providerId"->"provider_id";case "libraryId"->"library_id";case "folderId"->"folder_id";case "requesterId"->"requester_id";case "businessKey"->"business_key";case "logicalRequestHash"->"logical_request_hash";default->"execution_request_hash";};require(Objects.equals(manifest.get(field),submission.get(column)),PROVENANCE_UNAVAILABLE);}
  require(number(submission,"submission_no")==((Number)manifest.get("submissionNo")).longValue()&&meeting.equals(manifest.get("meetingId")),PROVENANCE_UNAVAILABLE);PublicationManifest.logical(manifest,(String)original.confirmation().get("source_manifest_hash"),(String)original.confirmation().get("input_fingerprint"),budget);require(JdbcPublicationService.spec(manifest,budget).equals(TranscriptReadGraph.spec(original.task())),PROVENANCE_UNAVAILABLE);identity.verify(submission,TranscriptReadGraph.spec(original.task()),manifest,original.executions());if(!operation.equals("PUBLICATION_LOCAL_RECOVERY"))require(actor.enterpriseId().equals(submission.get("requester_id")),PROVENANCE_UNAVAILABLE);
  List<Map<String,Object>> legacy=null;if(identity.requiresLegacyInventory(manifest)){legacy=tx.required(()->{var receipt=command(scope);access.require(access.lock(actor,meeting),MeetingAccess.Action.EDIT);require(receipt!=null,PROVENANCE_UNAVAILABLE);matchCommand(receipt,actor,meeting,operation,key,requestHash);var candidates=legacyCandidates(meeting,identity,bounds,budget);require(accepted(meeting,(String)receipt.get("result_id"),operation,bounds,budget,identity).equals(original),PROVENANCE_UNAVAILABLE);return candidates;});}
  var compatible=new ArrayList<Map<String,Object>>();if(legacy!=null)for(var candidate:legacy){var wire=PublicationManifest.read((String)candidate.get("originalManifest"),budget);require(JdbcPublicationService.spec(wire,budget).equals(candidate.get("originalSpec")),PROVENANCE_UNAVAILABLE);PublicationManifest.logical(wire,(String)original.confirmation().get("source_manifest_hash"),(String)original.confirmation().get("input_fingerprint"),budget);for(String field:List.of("publicationId","confirmationId","providerId","libraryId","folderId","requesterId","businessKey","logicalRequestHash","executionRequestHash")){String column=switch(field){case "publicationId"->"publication_id";case "confirmationId"->"confirmation_id";case "providerId"->"provider_id";case "libraryId"->"library_id";case "folderId"->"folder_id";case "requesterId"->"requester_id";case "businessKey"->"business_key";case "logicalRequestHash"->"logical_request_hash";default->"execution_request_hash";};require(Objects.equals(wire.get(field),candidate.get(column)),PROVENANCE_UNAVAILABLE);}require(((Number)wire.get("submissionNo")).longValue()==number(candidate,"submission_no"),PROVENANCE_UNAVAILABLE);var verified=new LinkedHashMap<String,Object>();for(String field:List.of("task_id","publication_id","submission_no"))verified.put(field,candidate.get(field));if(wire.containsKey("acceptanceBinding"))verified.put("acceptanceBinding",wire.get("acceptanceBinding"));compatible.add(Collections.unmodifiableMap(verified));}
  identity.verifyCommand(scope,requestHash,submission,manifest,compatible);final var legacyCapture=legacy;
  tx.required(()->{var receipt=command(scope);access.require(access.lock(actor,meeting),MeetingAccess.Action.EDIT);require(receipt!=null,PROVENANCE_UNAVAILABLE);matchCommand(receipt,actor,meeting,operation,key,requestHash);if(legacyCapture!=null)require(legacyCandidates(meeting,identity,bounds,budget).equals(legacyCapture),PROVENANCE_UNAVAILABLE);require(accepted(meeting,(String)receipt.get("result_id"),operation,bounds,budget,identity).equals(original),PROVENANCE_UNAVAILABLE);return null;});
  var result=new LinkedHashMap<String,Object>(submissionView(submission,Map.of("external_execution",original.executions())));result.put("operation",operation);result.put("resultKind","TASK");result.put("resultId",submission.get("task_id"));result.put("httpStatus",operation.equals("PUBLICATION_LOCAL_RECOVERY")?200:202);result.put("replayed",true);result.put("confirmation",publicFinalHeader(original.confirmation()));
  if(operation.equals("PUBLICATION_LOCAL_RECOVERY"))result.put("decision",JdbcMinutesSavedQueries.map("localState",submission.get("local_state"),"reason",submission.get("local_reason"),"decidedAt",textTime(submission.get("local_decided_at")),"decidedBy",submission.get("local_decided_by"),"attemptNoToken",submission.get("local_attempt_no").toString(),"executionId",submission.get("local_execution_id")));
  try{result.put("observation",current(actor,meeting));}catch(MeetingAccess.AccessDeniedException denied){throw denied;}catch(RuntimeException unavailable){result.put("observation",Map.of("availability","UNAVAILABLE","safeCode","PUBLICATION_READ_UNAVAILABLE"));}return Optional.of(Collections.unmodifiableMap(result));
 }
 private Map<String,Object> command(String scope){var rows=j.queryForList("SELECT actor_id,resource_id,operation,key_hash,request_hash,result_id,http_status,state FROM idempotency_record WHERE scope_hash=? FOR UPDATE",scope);require(rows.size()<=1,PROVENANCE_UNAVAILABLE);return rows.isEmpty()?null:rows.getFirst();}
 private static void matchCommand(Map<String,Object> r,Actor actor,String meeting,String operation,String key,String hash){if(!actor.enterpriseId().equals(r.get("actor_id"))||!meeting.equals(r.get("resource_id"))||!operation.equals(r.get("operation"))||!JdbcProcessingIntake.digest(key).equals(r.get("key_hash"))||!hash.equals(r.get("request_hash")))throw new ama.contract.TranscriptContracts.Failure(409,"IDEMPOTENCY_CONFLICT");require("SUCCEEDED".equals(r.get("state"))&&r.get("result_id") instanceof String&&number(r,"http_status")== (operation.equals("PUBLICATION_LOCAL_RECOVERY")?200:202),PROVENANCE_UNAVAILABLE);}

 private Map<String,Object> acceptedSubmission(String meeting,String task,boolean lock){var rows=j.queryForList("SELECT s.task_id,s.publication_id,s.submission_no,s.confirmation_id,s.provider_id,s.business_key,s.library_id,s.folder_id,s.requester_id,s.logical_request_hash,s.execution_request_hash,s.local_state,s.local_reason,s.local_decided_at,s.local_decided_by,s.local_attempt_no,s.local_execution_id,OCTET_LENGTH(s.request_manifest) manifest_bytes,CHAR_LENGTH(s.request_manifest) manifest_scalars,OCTET_LENGTH(CONVERT(s.request_manifest USING utf16))/2 manifest_utf16 FROM publication_submission s JOIN publication p ON p.id=s.publication_id WHERE s.task_id=? AND p.meeting_id=?"+(lock?" FOR UPDATE":""),task,meeting);require(rows.size()==1,PROVENANCE_UNAVAILABLE);return rows.getFirst();}
 private Accepted accepted(String meeting,String task,String operation,Bounds bounds,TranscriptAcquisitionBudget.Ledger budget,PublicationReplayIdentity identity){
  storedTaskId(task);var s=acceptedSubmission(meeting,task,false);
  require(j.queryForList("SELECT id FROM publication WHERE id=? AND meeting_id=? FOR UPDATE",s.get("publication_id"),meeting).size()==1,PROVENANCE_UNAVAILABLE);
  var finals=j.queryForList("SELECT id,meeting_id,meeting_revision,info_revision_id,roster_revision_id,transcript_confirmation_id,minutes_revision_id,material_snapshot_id,element_set_id,template_revision_id,exclusion_revision_id,source_manifest_hash,input_fingerprint,confirmed_by,confirmed_at FROM final_confirmation WHERE id=? AND meeting_id=? FOR UPDATE",s.get("confirmation_id"),meeting);require(finals.size()==1,PROVENANCE_UNAVAILABLE);
  require(s.equals(acceptedSubmission(meeting,task,true)),PROVENANCE_UNAVAILABLE);
  if(operation.equals("PUBLICATION_LOCAL_RECOVERY"))require("NEVER_MARKED".equals(s.get("local_state"))&&s.get("local_decided_at")!=null&&s.get("local_reason")!=null&&s.get("local_attempt_no")!=null&&s.get("local_decided_by")!=null,PROVENANCE_UNAVAILABLE);
  String executionSql="SELECT id,operation_id,execution_no,task_id,request_hash,OCTET_LENGTH(request_manifest) manifest_bytes FROM external_execution WHERE task_id=? ORDER BY operation_id,execution_no LIMIT 2";
  var discoveredExecutions=j.queryForList(executionSql,task);require(discoveredExecutions.size()<=1,PROVENANCE_UNAVAILABLE);
  // Control headers precede task; then all operations precede all execution rows.
  var attempts=j.queryForList("SELECT id,publication_id,confirmation_id,operation_id,execution_id,kind FROM publication_attempt WHERE execution_id IN (SELECT id FROM external_execution WHERE task_id=?) ORDER BY id LIMIT 257 FOR UPDATE",task);require(attempts.size()<=Math.min(256,bounds.limits().tasks()),BUDGET_EXCEEDED);
  var tasks=j.queryForList("SELECT id,task_type,pool,subject_kind,subject_id,producer_key,input_kind,input_id,input_fingerprint,business_version,priority,cancel_epoch,max_attempts FROM durable_task WHERE id=? FOR UPDATE",task);require(tasks.size()==1,PROVENANCE_UNAVAILABLE);var t=tasks.getFirst();require("MEETING".equals(t.get("subject_kind"))&&meeting.equals(t.get("subject_id"))&&"PUBLICATION".equals(t.get("input_kind"))&&s.get("publication_id").equals(t.get("input_id")),PROVENANCE_UNAVAILABLE);
  if(!discoveredExecutions.isEmpty()){var e=discoveredExecutions.getFirst();var ops=j.queryForList("SELECT business_key,operation_kind,subject_kind,subject_id FROM external_operation WHERE id=? FOR UPDATE",e.get("operation_id"));require(ops.size()==1&&s.get("business_key").equals(ops.getFirst().get("business_key"))&&meeting.equals(ops.getFirst().get("subject_id"))&&"MEETING".equals(ops.getFirst().get("subject_kind"))&&"KNOWLEDGE_PUBLISH".equals(ops.getFirst().get("operation_kind")),PROVENANCE_UNAVAILABLE);}
  var executions=j.queryForList(executionSql+" FOR UPDATE",task);require(executions.equals(discoveredExecutions),PROVENANCE_UNAVAILABLE);
  long bytes=number(s,"manifest_bytes"),points=number(s,"manifest_scalars"),units=number(s,"manifest_utf16");require(bytes>0&&bytes<=Math.min(65536,bounds.archive().maxManifestBytes()),BUDGET_EXCEEDED);budget.text(bytes,points,units,4,false);String manifest=j.queryForObject("SELECT request_manifest FROM publication_submission WHERE task_id=? AND OCTET_LENGTH(request_manifest)=? AND CHAR_LENGTH(request_manifest)=? AND OCTET_LENGTH(CONVERT(request_manifest USING utf16))/2=?",String.class,task,bytes,points,units);require(manifest!=null,PROVENANCE_UNAVAILABLE);
  if(!executions.isEmpty()){var e=executions.getFirst();require(s.get("execution_request_hash").equals(e.get("request_hash"))&&number(e,"manifest_bytes")==bytes,PROVENANCE_UNAVAILABLE);budget.text(bytes,points,units,2,false);String wire=j.queryForObject("SELECT request_manifest FROM external_execution WHERE id=? AND OCTET_LENGTH(request_manifest)=? AND CHAR_LENGTH(request_manifest)=? AND OCTET_LENGTH(CONVERT(request_manifest USING utf16))/2=?",String.class,e.get("id"),bytes,points,units);require(manifest.equals(wire),PROVENANCE_UNAVAILABLE);for(var a:attempts)require(s.get("publication_id").equals(a.get("publication_id"))&&s.get("confirmation_id").equals(a.get("confirmation_id"))&&e.get("operation_id").equals(a.get("operation_id"))&&e.get("id").equals(a.get("execution_id")),PROVENANCE_UNAVAILABLE);}
  return new Accepted(s,t,finals.getFirst(),executions,attempts,manifest);
 }
 /** Legacy fallback only: capture immutable acceptance/spec data under fresh owner/root locks.
  * Task full specs are immutable and read without acquiring task locks ahead of attempt controls. */
 private List<Map<String,Object>> legacyCandidates(String meeting,PublicationReplayIdentity identity,Bounds bounds,TranscriptAcquisitionBudget.Ledger budget){
  require(j.queryForList("SELECT id FROM publication WHERE id=? AND meeting_id=? FOR UPDATE",String.class,identity.publication(),meeting).size()==1,PROVENANCE_UNAVAILABLE);require(j.queryForList("SELECT id FROM final_confirmation WHERE id=? AND meeting_id=? FOR UPDATE",String.class,identity.confirmation(),meeting).size()==1,PROVENANCE_UNAVAILABLE);
  int cap=Math.min(256,bounds.limits().tasks());var bindings=bounded("SELECT task_id,publication_id,submission_no,confirmation_id,provider_id,library_id,folder_id,requester_id,business_key,logical_request_hash,execution_request_hash,OCTET_LENGTH(request_manifest) manifest_bytes,CHAR_LENGTH(request_manifest) manifest_scalars,OCTET_LENGTH(CONVERT(request_manifest USING utf16))/2 manifest_utf16 FROM publication_submission WHERE publication_id=? ORDER BY task_id",cap,budget,identity.publication());
  String sql="SELECT id,task_type,pool,subject_kind,subject_id,producer_key,input_kind,input_id,input_fingerprint,business_version,priority,cancel_epoch,max_attempts FROM durable_task WHERE subject_kind='MEETING' AND subject_id=? AND input_kind='PUBLICATION' AND input_id=? ORDER BY id";long count=j.queryForObject("SELECT COUNT(*) FROM ("+sql+" LIMIT "+(cap+1)+") legacy_task_count",Long.class,meeting,identity.publication());require(count<=cap&&count<=budget.remainingRows(),BUDGET_EXCEEDED);budget.admitCapture(Math.multiplyExact(count+1,65536),Math.multiplyExact(count+1,16384),Math.multiplyExact(count+1,32768),2);var tasks=metadata(j.queryForList(sql+" LIMIT "+(cap+1),meeting,identity.publication()),budget);require(tasks.size()==count,PROVENANCE_UNAVAILABLE);var candidates=new ArrayList<Map<String,Object>>();
  for(var binding:bindings){var selected=tasks.stream().filter(t->binding.get("task_id").equals(t.get("id"))).toList();require(selected.size()==1,PROVENANCE_UNAVAILABLE);if(!identity.compatible(binding,selected.getFirst()))continue;long bytes=number(binding,"manifest_bytes"),points=number(binding,"manifest_scalars"),units=number(binding,"manifest_utf16");require(bytes>0&&bytes<=Math.min(65536,bounds.archive().maxManifestBytes()),BUDGET_EXCEEDED);budget.text(bytes,points,units,4,false);String wire=j.queryForObject("SELECT request_manifest FROM publication_submission WHERE task_id=? AND OCTET_LENGTH(request_manifest)=? AND CHAR_LENGTH(request_manifest)=? AND OCTET_LENGTH(CONVERT(request_manifest USING utf16))/2=?",String.class,binding.get("task_id"),bytes,points,units);require(wire!=null,PROVENANCE_UNAVAILABLE);var candidate=new LinkedHashMap<String,Object>(binding);candidate.put("originalManifest",wire);candidate.put("originalSpec",TranscriptReadGraph.spec(selected.getFirst()));candidates.add(Collections.unmodifiableMap(candidate));}return List.copyOf(candidates);
 }
 static void storedTaskId(String task){try{uuid(task);}catch(RuntimeException invalid){throw fail(PROVENANCE_UNAVAILABLE);}}
 private static Object textTime(Object value){return value==null?null:value.toString();}
 static Map<String,Object> publicFinalHeader(Map<String,Object> row){return JdbcMinutesSavedQueries.map("confirmationId",row.get("id"),"meetingRevisionToken",row.get("meeting_revision").toString(),"confirmedBy",row.get("confirmed_by"),"confirmedAt",textTime(row.get("confirmed_at")),"minutesRevisionId",row.get("minutes_revision_id"),"elementSetId",row.get("element_set_id"),"transcriptConfirmationId",row.get("transcript_confirmation_id"));}
 private List<Map<String,Object>> header(String meeting){var rows=j.queryForList("SELECT id,meeting_id,confirmation_id,business_key,library_id,folder_id,state,revision FROM publication WHERE meeting_id=? ORDER BY id LIMIT 2 FOR UPDATE",meeting);require(rows.size()<=1,PROVENANCE_UNAVAILABLE);return rows;}
 private Snapshot capture(Actor actor,String meeting,Map<String,Object> pub,Bounds bounds){
  return capture(actor,meeting,pub,bounds,bounds.ledger());
 }
 private Snapshot capture(Actor actor,String meeting,Map<String,Object> pub,Bounds bounds,TranscriptAcquisitionBudget.Ledger budget){
  var root=j.queryForMap("SELECT id,owner_id,revision,access_revision,cancel_epoch,lifecycle,governance_state,stage,final_confirmation_id,ever_published,info_revision_id,roster_revision_id,transcript_confirmation_id,minutes_revision_id,material_snapshot_id,element_set_id,template_revision_id,exclusion_revision_id FROM meeting WHERE id=?",meeting);String publication=(String)pub.get("id");var rows=new LinkedHashMap<String,List<Map<String,Object>>>();int cap=Math.min(256,bounds.limits().tasks());
  rows.put("final_confirmation",bounded("SELECT id,meeting_id,meeting_revision,info_revision_id,roster_revision_id,transcript_confirmation_id,minutes_revision_id,material_snapshot_id,element_set_id,template_revision_id,exclusion_revision_id FROM final_confirmation WHERE id=? AND meeting_id=?",1,budget,pub.get("confirmation_id"),meeting));
  rows.put("publication_submission",bounded("SELECT task_id,publication_id,submission_no,confirmation_id,provider_id,business_key,library_id,folder_id,requester_id,logical_request_hash,execution_request_hash,local_state,local_reason,local_decided_at,local_decided_by,local_attempt_no,local_execution_id,created_at FROM publication_submission WHERE publication_id=? ORDER BY task_id",cap,budget,publication));
  rows.put("external_document_mapping",bounded("SELECT publication_id,provider_id,external_document_id,authority_state,verified_at FROM external_document_mapping WHERE publication_id=? ORDER BY publication_id",1,budget,publication));
  rows.put("publication_attempt",bounded("SELECT id,publication_id,confirmation_id,operation_id,execution_id,kind,outcome,created_at,finished_at FROM publication_attempt WHERE publication_id=? ORDER BY id",cap,budget,publication));
  // Whole meeting histories are counted before filtering, preserving the R1 cumulative sentinel.
  var tasks=bounded("SELECT id,task_type,pool,subject_kind,subject_id,producer_key,input_kind,input_id,input_fingerprint,business_version,priority,cancel_epoch,state,attempt,max_attempts,output_kind,output_id FROM durable_task WHERE subject_kind='MEETING' AND subject_id=? ORDER BY id",cap,budget,meeting);
  var ordinary=bounded("SELECT task_id,attempt,ended_at,outcome FROM task_attempt WHERE task_id IN (SELECT id FROM durable_task WHERE subject_kind='MEETING' AND subject_id=?) ORDER BY task_id,attempt",cap,budget,meeting);
  var operations=bounded("SELECT id,operation_kind,business_key,subject_kind,subject_id,request_hash,state,current_execution_no,reconcile_epoch,CASE WHEN external_result_id IS NULL THEN 0 ELSE 1 END external_result_present FROM external_operation WHERE subject_kind='MEETING' AND subject_id=? ORDER BY id",cap,budget,meeting);
  var executions=bounded("SELECT id,operation_id,execution_no,task_id,state,request_hash,marked_at,task_attempt,no_effect_basis,no_effect_verified_at,finished_at FROM external_execution WHERE operation_id IN (SELECT id FROM external_operation WHERE subject_kind='MEETING' AND subject_id=?) ORDER BY operation_id,execution_no",cap,budget,meeting);
  var selectedTasks=tasks.stream().filter(t->"PUBLICATION".equals(t.get("input_kind"))&&publication.equals(t.get("input_id"))).toList();var ids=new HashSet<String>();for(var t:selectedTasks)require(ids.add((String)t.get("id")),PROVENANCE_UNAVAILABLE);
  var selectedExecutions=executions.stream().filter(e->ids.contains(e.get("task_id"))).toList();var selectedOps=operations.stream().filter(o->((String)o.get("business_key")).startsWith(publication+":")||selectedExecutions.stream().anyMatch(e->o.get("id").equals(e.get("operation_id")))).toList();
  rows.put("durable_task",selectedTasks);rows.put("task_attempt",ordinary.stream().filter(a->ids.contains(a.get("task_id"))).toList());rows.put("external_operation",selectedOps);rows.put("external_execution",selectedExecutions);validateAssociations(meeting,publication,rows);return new Snapshot(root,pub,Map.copyOf(rows),actor.enterpriseId().equals(root.get("owner_id")));
 }
 private static void validateAssociations(String meeting,String publication,Map<String,List<Map<String,Object>>> rows){
  var submissions=rows.get("publication_submission");require(submissions.size()==rows.get("durable_task").size(),PROVENANCE_UNAVAILABLE);var taskIds=new HashSet<String>();
  for(var s:submissions){String task=(String)s.get("task_id");require(taskIds.add(task),PROVENANCE_UNAVAILABLE);var matches=rows.get("durable_task").stream().filter(t->task.equals(t.get("id"))).toList();require(matches.size()==1,PROVENANCE_UNAVAILABLE);var t=matches.getFirst();require("KNOWLEDGE_PUBLISH_V1".equals(t.get("task_type"))&&"KNOWLEDGE_PUBLISH".equals(t.get("pool"))&&meeting.equals(t.get("subject_id"))&&s.get("logical_request_hash").equals(t.get("input_fingerprint"))&&(publication+":"+s.get("confirmation_id")).equals(s.get("business_key")),PROVENANCE_UNAVAILABLE);
   var executions=rows.get("external_execution").stream().filter(e->task.equals(e.get("task_id"))).toList();require(executions.size()<=1,PROVENANCE_UNAVAILABLE);for(var e:executions){require(s.get("execution_request_hash").equals(e.get("request_hash")),PROVENANCE_UNAVAILABLE);var ops=rows.get("external_operation").stream().filter(o->e.get("operation_id").equals(o.get("id"))).toList();require(ops.size()==1&&s.get("business_key").equals(ops.getFirst().get("business_key"))&&"KNOWLEDGE_PUBLISH".equals(ops.getFirst().get("operation_kind")),PROVENANCE_UNAVAILABLE);}
  }
  for(var a:rows.get("publication_attempt")){var es=rows.get("external_execution").stream().filter(e->a.get("execution_id").equals(e.get("id"))&&a.get("operation_id").equals(e.get("operation_id"))).toList();require(es.size()==1,PROVENANCE_UNAVAILABLE);var ss=submissions.stream().filter(s->es.getFirst().get("task_id").equals(s.get("task_id"))).toList();require(ss.size()==1&&a.get("confirmation_id").equals(ss.getFirst().get("confirmation_id")),PROVENANCE_UNAVAILABLE);}
  for(var o:rows.get("external_operation"))require(rows.get("external_execution").stream().anyMatch(e->o.get("id").equals(e.get("operation_id"))),PROVENANCE_UNAVAILABLE);
 }
 private List<Map<String,Object>> bounded(String sql,int maximum,TranscriptAcquisitionBudget.Ledger budget,Object...args){
  long count=j.queryForObject("SELECT COUNT(*) FROM ("+sql+" LIMIT "+(maximum+1)+") publication_read_count",Long.class,args);require(count<=maximum&&count<=budget.remainingRows(),BUDGET_EXCEEDED);budget.admitCapture(Math.multiplyExact(count+1,65536),Math.multiplyExact(count+1,16384),Math.multiplyExact(count+1,32768),2);
  var found=j.queryForList(sql+" LIMIT "+(maximum+1)+" FOR UPDATE",args);require(found.size()==count,PROVENANCE_UNAVAILABLE);return metadata(found,budget);
 }
 record PageQuery(String sql,List<Object> args){PageQuery{args=List.copyOf(args);}}
 static PageQuery attemptPage(String publication,PublicationHistoryCursor.Key before){var args=new ArrayList<Object>();args.add(publication);String sql="SELECT id,created_at FROM publication_attempt WHERE publication_id=?";if(before!=null){sql+=" AND (created_at<? OR (created_at=? AND id<?))";args.add(before.created());args.add(before.created());args.add(before.id());}return new PageQuery(sql+" ORDER BY created_at DESC,id DESC",args);}
 private List<Map<String,Object>> page(String sql,int cap,TranscriptAcquisitionBudget.Ledger budget,Object...args){long count=j.queryForObject("SELECT COUNT(*) FROM ("+sql+" LIMIT "+cap+") publication_page_count",Long.class,args);require(count<=cap&&count<=budget.remainingRows(),BUDGET_EXCEEDED);budget.admitCapture(Math.multiplyExact(count+1,65536),Math.multiplyExact(count+1,16384),Math.multiplyExact(count+1,32768),2);var found=j.queryForList(sql+" LIMIT "+cap+" FOR UPDATE",args);require(found.size()==count,PROVENANCE_UNAVAILABLE);return metadata(found,budget);}
 private static List<Map<String,Object>> metadata(List<Map<String,Object>> found,TranscriptAcquisitionBudget.Ledger budget){var rows=new ArrayList<Map<String,Object>>();for(var raw:found){budget.row(raw.size());var row=new LinkedHashMap<String,Object>();for(var cell:raw.entrySet()){Object value=normalizeMetadata(cell.getValue());if(value instanceof String text){scalars(text);require(text.length()<=512,BUDGET_EXCEEDED);budget.capture(text.getBytes(StandardCharsets.UTF_8).length,text.codePointCount(0,text.length()),text.length(),3);}row.put(cell.getKey(),value);}rows.add(Collections.unmodifiableMap(row));}return List.copyOf(rows);}

 static Object normalizeMetadata(Object value){if(value instanceof Number number)return new java.math.BigDecimal(number.toString()).longValueExact();if(value instanceof java.sql.Timestamp time)return time.toLocalDateTime().toString();if(value instanceof java.time.temporal.TemporalAccessor time)return time.toString();return value;}
 private static Map<String,Object> submissionView(Map<String,Object> row,Map<String,List<Map<String,Object>>> rows){var result=JdbcMinutesSavedQueries.map("taskId",row.get("task_id"),"publicationId",row.get("publication_id"),"submissionNoToken",row.get("submission_no").toString(),"confirmationId",row.get("confirmation_id"),"providerId",row.get("provider_id"),"libraryId",row.get("library_id"),"folderId",row.get("folder_id"),"localState",row.get("local_state"),"localReason",row.get("local_reason"));var copy=new LinkedHashMap<String,Object>(result);var executions=rows.get("external_execution").stream().filter(e->row.get("task_id").equals(e.get("task_id"))).toList();copy.put("executionId",executions.isEmpty()?null:executions.getFirst().get("id"));copy.put("executionNoToken",executions.isEmpty()?null:executions.getFirst().get("execution_no").toString());copy.put("localDecision",row.get("local_decided_at")==null?null:JdbcMinutesSavedQueries.map("decidedAt",textTime(row.get("local_decided_at")),"decidedBy",row.get("local_decided_by"),"attemptNoToken",row.get("local_attempt_no").toString(),"executionId",row.get("local_execution_id")));return copy;}
 private static Map<String,Object> attemptView(Map<String,Object> a,Map<String,List<Map<String,Object>>> rows){var e=rows.get("external_execution").stream().filter(x->a.get("execution_id").equals(x.get("id"))).findFirst().orElseThrow();return JdbcMinutesSavedQueries.map("attemptId",a.get("id"),"confirmationId",a.get("confirmation_id"),"operationId",a.get("operation_id"),"executionId",a.get("execution_id"),"kind",a.get("kind"),"rawOutcome",a.get("outcome"),"remoteOutcome",remoteOutcome(e),"applicationOutcome",attemptApplication(a,e,rows),"manualLocked",attemptApplication(a,e,rows).equals("FENCED_MANUAL"),"lookupPending",attemptApplication(a,e,rows).equals("PENDING_LOOKUP"),"createdAt",a.get("created_at"),"finishedAt",a.get("finished_at"));}
 private static String remoteOutcome(Map<String,Object> execution){return switch((String)execution.get("state")){case "SUCCEEDED"->"SUCCESS";case "FAILED"->"FAILED";case "MARKED","UNKNOWN"->"UNKNOWN";default->"NOT_OBSERVED";};}
 private static String attemptApplication(Map<String,Object> attempt,Map<String,Object> execution,Map<String,List<Map<String,Object>>> rows){boolean manual=rows.getOrDefault("external_operation",List.of()).stream().anyMatch(o->execution.get("operation_id").equals(o.get("id"))&&"MANUAL_REQUIRED".equals(o.get("state")));if(manual)return "FENCED_MANUAL";if(Set.of("MARKED","UNKNOWN").contains(execution.get("state")))return "PENDING_LOOKUP";if("SUCCEEDED".equals(execution.get("state")))return "SUCCESS".equals(attempt.get("outcome"))&&attempt.get("finished_at")!=null?"APPLIED":"FENCED_MANUAL";if("FAILED".equals(execution.get("state")))return "FAILED".equals(attempt.get("outcome"))&&attempt.get("finished_at")!=null?"APPLIED":"FENCED_MANUAL";return "PENDING";}
 private static long number(Map<String,Object> row,String name){return ((Number)row.get(name)).longValue();}
 private static ama.contract.TranscriptContracts.Failure missing(){return new ama.contract.TranscriptContracts.Failure(404,"PUBLICATION_NOT_FOUND");}
}
